const fs=require('fs'),cp=require('child_process'),vm=require('vm'),assert=require('assert/strict');
const base='a6345da6bb069a79e8cf7ab5f235fabf4ac9aa4a',old=p=>JSON.parse(cp.execFileSync('git',['show',base+':'+p],{maxBuffer:30e6})),read=p=>JSON.parse(fs.readFileSync(p));
const batch=read('data/research-coverage-20261014/events-bundle.json'),adds=batch.items.filter(i=>i.action==='add').map(i=>i.event),updates=new Map(batch.items.filter(i=>i.action==='update').map(i=>[i.event.id,i.event]));
const before=old('public/belgrade/events.json'),after=read('public/belgrade/events.json');assert.equal(after.events.length,494);assert.equal(adds.length,74);assert.equal(updates.size,1);const indexed=new Map(after.events.map(e=>[e.id,e]));assert.equal(indexed.size,after.events.length);
for(const e of before.events){assert(indexed.has(e.id));if(!updates.has(e.id))assert.deepEqual(indexed.get(e.id),e,'prior event remains intact '+e.id);}
for(const e of adds){assert.deepEqual(indexed.get(e.id),e);assert(e.date>='2026-10-14'&&e.date<='2026-10-21');assert(Number.isFinite(e.lat)&&Number.isFinite(e.lng));assert(e.coordinateSource&&e.address&&e.sourceUrl);assert(e.lat>44.6&&e.lat<45&&e.lng>20.1&&e.lng<20.8);assert.equal(e.soldOut||false,e.status==='sold_out');assert(e.startAt&&e.timezone==='Europe/Belgrade');assert(!['cancelled','canceled'].includes(e.status));}
assert.equal(adds.filter(e=>e.soldOut).length,7);const calendarOnly=adds.filter(e=>e.ticketCalendarEndAt);assert.equal(calendarOnly.length,18);for(const e of calendarOnly){assert.equal(e.end,null);assert(!e.endAt);assert.equal(e.endTimeVerified,false);}for(const city of ['','moscow/','palo-alto/','paris/','london/'])assert.deepEqual(read('public/'+city+'events.json'),old('public/'+city+'events.json'),'other city events unchanged');
const pbefore=old('public/places.json'),pafter=read('public/places.json'),pr=read('data/research-coverage-20261014/places-import-result.json'),pi=new Map(pafter.map(p=>[p.id,p])),allowed=new Set(pr.updated.map(p=>p.id));assert.equal(pafter.length,pbefore.length+2);for(const p of pbefore){const n=pi.get(p.id);assert(n);assert.equal(n.lat,p.lat);assert.equal(n.lng,p.lng);assert.equal(n.coordinateSource,p.coordinateSource);if(!allowed.has(p.id))assert.deepEqual(n,p);}
assert.equal(pr.updated.length,15);assert.equal(pafter.filter(p=>!p.address).length,1677);
for(const id of pr.added)assert.equal(pi.get(id).coordinateAccuracy,'building');
for(const city of ['belgrade/','moscow/','palo-alto/','paris/','london/'])assert.deepEqual(read('public/'+city+'places.json'),old('public/'+city+'places.json'),'unrelated places unchanged');
for(const p of cp.execFileSync('git',['ls-tree','-r','--name-only',base,'public'],{encoding:'utf8'}).trim().split('\n'))if(/\.(js|css|html|apk|zip)$/.test(p))assert.deepEqual(fs.readFileSync(p),cp.execFileSync('git',['show',base+':'+p],{maxBuffer:30e6}),'UI/APK/download unchanged '+p);
// Run all visibility model fixtures and all current six-city RU/EN events, excluding the old release-specific equality assertions.
vm.runInNewContext(fs.readFileSync('scripts/test-live-expiry.cjs','utf8').split('const baseline=')[0],{require,console,module:{exports:{}}});
console.log('PASS: 74 verified additions, 7 explicitly sold out, 1 historical correction; all other events/places and every UI/APK/download unchanged; 2 new building-level places and 15 enrichments; expiry/DST/museum/cinema fixtures retained.');
